<script>
(() => {
 const form=document.getElementById('department-application'),status=document.getElementById('draft-status'),panels=[...form.querySelectorAll('[data-wizard-panel]')],steps=[...document.querySelectorAll('[data-wizard-step]')];
 let step=<?php echo e($errors->any()?1:(int)$draft->step); ?>,timer,saveQueue=Promise.resolve(),revision=0,catalogue=<?php echo json_encode($selected?->faculties ?? [], 15, 512) ?>,searchSequence=0;
 const directory=<?php echo json_encode(route('academic.directory'), 15, 512) ?>,draftUrl=<?php echo json_encode(route('department.onboarding.draft'), 15, 512) ?>,csrf=form.querySelector('[name=_token]').value;
 const field=name=>form.elements.namedItem(name),option=(value,label)=>{const item=document.createElement('option');item.value=value;item.textContent=label;return item;};
 const save=()=>{const savedRevision=revision;const data={step};for(const [key,value] of new FormData(form))if(key!=='_token'&&!(value instanceof File)&&key!=='authority_confirmed')data[key]=value;
   saveQueue=saveQueue.catch(()=>{}).then(async()=>{status.textContent='Saving progress…';const result=await fetch(draftUrl,{method:'PUT',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(data)});if(!result.ok)throw Error('save');if(revision===savedRevision)status.textContent='Progress saved. You can return to this application later.';}).catch(()=>{status.textContent='Progress could not be saved. Keep this page open and try again. You can still submit the application.';});return saveQueue;};
 const summary=()=>{const target=document.getElementById('application-summary');target.replaceChildren();for(const [label,name]of [['Institution','university_id'],['Faculty / school','faculty_name'],['Department','department_name'],['Classification','classification'],['Representative role','representative_title'],['Official email','official_email'],['Phone','official_phone'],['Plan','plan_key']]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.className='text-xs text-slate-500';dt.textContent=label;dd.textContent=name==='university_id'?document.getElementById('selected-institution').textContent:(field(name).value||'Not provided');row.append(dt,dd);target.append(row);}};
 const show=focus=>{step=Math.max(1,Math.min(4,step));panels.forEach((panel,i)=>panel.hidden=i+1!==step);steps.forEach((button,i)=>{if(i+1===step)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');});form.querySelector('[data-wizard-back]').hidden=step===1;form.querySelector('[data-wizard-next]').hidden=step===4;form.querySelector('[data-wizard-submit]').hidden=step!==4;if(step===4)summary();if(focus)panels[step-1].querySelector('h2').focus();};
 const valid=()=>{if(step===1&&!field('university_id').value){status.textContent='Search and choose an institution first.';document.getElementById('institution-search').focus();return false;}for(const input of panels[step-1].querySelectorAll('input,select,textarea'))if(!input.checkValidity()){input.reportValidity();return false;}return true;};
 const fillDepartments=(selected='')=>{const faculty=catalogue.find(item=>String(item.id)===field('faculty_id').value);field('department_id').replaceChildren(option('','Register a department not listed'));for(const item of faculty?.departments||[])field('department_id').append(option(item.id,`${item.name} · ${String(item.adoption_status).replaceAll('_',' ')}`));field('department_id').value=selected;if(faculty)field('faculty_name').value=faculty.name;field('faculty_name').readOnly=Boolean(faculty);};
 const fillFaculties=(selectedFaculty='',selectedDepartment='')=>{field('faculty_id').replaceChildren(option('','My faculty/school is not listed'));for(const item of catalogue)field('faculty_id').append(option(item.id,item.name));field('faculty_id').value=selectedFaculty;fillDepartments(selectedDepartment);};
 fillFaculties(<?php echo json_encode((string)($values['faculty_id']??''), 15, 512) ?>,<?php echo json_encode((string)($values['department_id']??''), 15, 512) ?>);
 field('faculty_id').addEventListener('change',()=>{if(!field('faculty_id').value)field('faculty_name').value='';fillDepartments();});
 field('department_id').addEventListener('change',()=>{const department=catalogue.flatMap(f=>f.departments).find(d=>String(d.id)===field('department_id').value);field('department_name').readOnly=Boolean(department);field('department_name').value=department?.name||'';});
 const search=async()=>{const q=document.getElementById('institution-search').value.trim();if(q.length<2){status.textContent='Type at least two characters to search.';return;}const sequence=++searchSequence;const target=document.getElementById('institution-results');target.textContent='Searching…';try{const response=await fetch(directory+'?q='+encodeURIComponent(q),{headers:{Accept:'application/json'}});if(!response.ok)throw Error();const data=await response.json();if(sequence!==searchSequence)return;target.replaceChildren();for(const institution of data.institutions){const button=document.createElement('button');button.type='button';button.textContent=`${institution.name} · ${String(institution.adoption_status).replaceAll('_',' ')}`;button.addEventListener('click',async()=>{try{const result=await fetch(directory+'?university_id='+institution.id,{headers:{Accept:'application/json'}});if(!result.ok)throw Error();const details=await result.json();catalogue=details.faculties;field('university_id').value=institution.id;document.getElementById('selected-institution').textContent=institution.name;field('faculty_name').value='';field('department_name').value='';field('department_name').readOnly=false;fillFaculties();target.replaceChildren();save();}catch{status.textContent='Institution details could not be loaded. Try again.';}});target.append(button);}if(!data.institutions.length)target.textContent='No match found. Request a missing institution below.';}catch{target.textContent='Search could not be completed. Please try again.';}};
 document.getElementById('institution-search-button').addEventListener('click',search);document.getElementById('institution-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search();}});
 form.querySelector('[data-wizard-next]').addEventListener('click',()=>{if(valid()){step++;show(true);save();}});form.querySelector('[data-wizard-back]').addEventListener('click',()=>{step--;show(true);save();});steps.forEach((button,i)=>button.addEventListener('click',()=>{if(i+1<step||valid()){step=i+1;show(true);save();}}));
 form.addEventListener('input',()=>{revision++;status.textContent='Unsaved changes…';clearTimeout(timer);timer=setTimeout(save,750);});form.addEventListener('change',()=>{revision++;status.textContent='Unsaved changes…';clearTimeout(timer);timer=setTimeout(save,150);});
 form.noValidate=true;form.addEventListener('submit',async e=>{for(let i=0;i<panels.length;i++){const invalid=[...panels[i].querySelectorAll('input,select,textarea')].find(input=>!input.checkValidity());if(invalid){e.preventDefault();step=i+1;show(true);invalid.reportValidity();return;}}if(!field('university_id').value){e.preventDefault();step=1;show(true);valid();return;}e.preventDefault();clearTimeout(timer);form.querySelector('[data-wizard-submit]').disabled=true;await save();HTMLFormElement.prototype.submit.call(form);});show(false);
})();
</script>
